def pin(name,h):
 raw=(root/name).read_bytes()
 if sha256(raw).hexdigest()!=h:raise ValueError('PIN:'+name)
 return json.loads(raw)
f=pin('frontier-20261028-midpoint-derivative-cone-obstruction-frozen-v1.json','016e97ece7973285b69ba9275e87580e7b23f6fd0816e120b3dd854470f86c22');box=pin(f['box_file'],f['box_sha256']);good=pin(f['known_common_numerator_file'],f['known_common_numerator_sha256'])
lo=list(map(F,box['lower']));hi=list(map(F,box['upper']));b=list(map(F,good['b']));mid=[(lo[j]+hi[j])/2 for j in range(7)]+[F(1)]
if not all(0<lo[j]<hi[j] for j in range(7)) or not all(v>0 for v in b) or b[7]!=1:raise ValueError('INPUT')
def corners(lo,hi):
 out=[]
 for e,o in ((0,0),(0,1),(1,0),(1,1)):
  out.append([(lo[j] if not(e if j%2==0 else o) else hi[j]) if j%4 in (0,1) else (hi[j] if not(e if j%2==0 else o) else lo[j]) for j in range(7)]+[F(1)])
 return out
