def det(A):
 n=len(A);den=lcm(*(v.denominator for row in A for v in row));M=[[int(v*den) for v in row] for row in A];sgn=1;prev=1
 for k in range(n-1):
  if not M[k][k]:
   r=next((r for r in range(k+1,n) if M[r][k]),None)
   if r is None:return F(0)
   M[r],M[k]=M[k],M[r];sgn=-sgn
  pivot=M[k][k]
  for i in range(k+1,n):
   for j in range(k+1,n):
    z=M[i][j]*pivot-M[i][k]*M[k][j]
    if z%prev:raise ValueError('BAREISS')
    M[i][j]=z//prev
  for i in range(k+1,n):M[i][k]=0
  prev=pivot
 return F(sgn*M[-1][-1],den**n)
